//! The matching set (06-roadmap workstream 10): a data-driven test over
//! `tests/sites/sites.json`.
//!
//! The file is generated by `tests/sites/gen.rs` and committed so the test
//! is deterministic and the set is reviewable as data. When the generator
//! changes, the first test fails and says how to refresh the file:
//!
//! ```text
//! LOCKDOWN_WRITE_SITES=1 cargo test -p lockdown-matcher --test sites
//! ```

#[path = "sites/gen.rs"]
mod generator;

use std::path::PathBuf;

use generator::{RelatedRow, Row, SiteSet};
use lockdown_matcher::related_origins::{RelatedOriginsCache, RelatedOriginsDoc};
use lockdown_matcher::{MatchDecision, MatchRule, MatcherData, Origin, SavedUrl, decide_with};

const COMMITTED: &str = include_str!("sites/sites.json");

fn sites_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(generator::SITES_PATH)
}

fn committed() -> SiteSet {
    serde_json::from_str(COMMITTED).expect("sites.json parses")
}

fn rule(text: &str) -> MatchRule {
    serde_json::from_value(serde_json::Value::String(text.into())).expect("a known rule")
}

fn decision_name(d: MatchDecision) -> String {
    serde_json::to_value(d)
        .unwrap()
        .as_str()
        .unwrap()
        .to_string()
}

/// Runs one row; `None` when it passes, else what went wrong.
fn run_row(row: &Row, data: &MatcherData) -> Option<String> {
    let saved = match SavedUrl::parse(&row.saved, rule(&row.rule)) {
        Ok(s) => s,
        Err(e) => {
            return Some(format!(
                "{}: saved '{}' did not parse: {e}",
                row.id, row.saved
            ));
        }
    };
    let got = match Origin::parse(&row.current) {
        Ok(current) => decision_name(decide_with(&saved, &current, data)),
        Err(_) => "error".to_string(),
    };
    if got == row.expected {
        None
    } else {
        Some(format!(
            "{} [{}]: saved {} ({}) vs {} → expected {}, got {} — {}",
            row.id, row.group, row.saved, row.rule, row.current, row.expected, got, row.note
        ))
    }
}

fn run_related(row: &RelatedRow) -> Option<String> {
    let mut cache = RelatedOriginsCache::new(row.max_age_secs);
    cache.insert(
        &row.rp_id,
        RelatedOriginsDoc {
            origins: row.origins.clone(),
        },
        row.fetched_at,
    );
    let origin = match Origin::parse(&row.origin) {
        Ok(o) => o,
        Err(e) => return Some(format!("{}: origin did not parse: {e}", row.id)),
    };
    let got = cache.allows(&row.rp_id, &origin, row.now);
    if got == row.expected {
        None
    } else {
        Some(format!(
            "{}: {} for {} → expected {}, got {} — {}",
            row.id, row.rp_id, row.origin, row.expected, got, row.note
        ))
    }
}

#[test]
fn the_committed_set_is_what_the_generator_makes() {
    let data = MatcherData::builtin().unwrap();
    let fresh = generator::render(&generator::generate(&data));
    if std::env::var_os("LOCKDOWN_WRITE_SITES").is_some() {
        std::fs::write(sites_path(), &fresh).expect("write sites.json");
    }
    assert!(
        fresh == COMMITTED,
        "tests/sites/sites.json is stale; refresh it with:\n  LOCKDOWN_WRITE_SITES=1 cargo test -p lockdown-matcher --test sites"
    );
}

#[test]
fn the_set_is_large_enough_and_balanced() {
    let set = committed();
    assert_eq!(set.set_version, generator::SET_VERSION);
    assert_eq!(set.rows, set.matches.len());
    assert_eq!(set.related_rows, set.related_origins.len());
    assert!(set.matches.len() >= 500, "{} match rows", set.matches.len());
    let mut by_group = std::collections::BTreeMap::new();
    let mut by_expected = std::collections::BTreeMap::new();
    for r in &set.matches {
        *by_group.entry(r.group.as_str()).or_insert(0usize) += 1;
        *by_expected.entry(r.expected.as_str()).or_insert(0usize) += 1;
    }
    for g in [
        "exact",
        "subdomain",
        "starts_with",
        "equivalent",
        "lookalike",
        "unrelated",
        "host-kinds",
    ] {
        assert!(
            by_group.get(g).copied().unwrap_or(0) >= 5,
            "group {g} is thin"
        );
    }
    for e in [
        "exact",
        "base_domain",
        "equivalent",
        "lookalike",
        "no_match",
        "error",
    ] {
        assert!(
            by_expected.get(e).copied().unwrap_or(0) >= 5,
            "expected {e} is thin"
        );
    }
    // Ids are unique.
    let ids: std::collections::BTreeSet<&str> = set.matches.iter().map(|r| r.id.as_str()).collect();
    assert_eq!(ids.len(), set.matches.len());
    eprintln!(
        "sites: {} match rows {by_group:?} {by_expected:?}; {} related rows",
        set.matches.len(),
        set.related_origins.len()
    );
}

#[test]
fn every_row_passes() {
    let data = MatcherData::builtin().unwrap();
    let set = committed();
    let failures: Vec<String> = set
        .matches
        .iter()
        .filter_map(|r| run_row(r, &data))
        .collect();
    assert!(
        failures.is_empty(),
        "{} of {} rows failed:\n{}",
        failures.len(),
        set.matches.len(),
        failures.join("\n")
    );
}

#[test]
fn every_related_origins_row_passes() {
    let set = committed();
    let failures: Vec<String> = set.related_origins.iter().filter_map(run_related).collect();
    assert!(
        failures.is_empty(),
        "{} of {} related rows failed:\n{}",
        failures.len(),
        set.related_origins.len(),
        failures.join("\n")
    );
}
